import { createClient, type SupabaseClient, type User } from "npm:@supabase/supabase-js@2";
import Razorpay from "npm:razorpay@2.9.4";

/* ============================== cors.ts ============================== */
// Security headers + CORS + body-size guard for every Edge Function.
//
// Hand-rolled equivalent of helmet() + cors() + body size cap for Deno.
// Every function in this project wraps its handler with `withSecurity()`
// so none of them ship without these protections.

const DEFAULT_ORIGINS = [
  "https://e-commerce-demo-website1.web.app",
  "https://my-sweet-bec4a.web.app",
  "http://localhost:5173",
];

function allowedOrigins(): string[] {
  const env = Deno.env.get("ALLOWED_ORIGINS");
  if (!env) return DEFAULT_ORIGINS;
  return env.split(",").map((s) => s.trim()).filter(Boolean);
}

function isOriginAllowed(origin: string): boolean {
  if (!origin) return true;
  const list = allowedOrigins();
  if (list.includes("*") || list.includes(origin)) return true;
  try {
    const url = new URL(origin);
    if (url.hostname.endsWith(".vercel.app") || url.hostname === "localhost" || url.hostname === "127.0.0.1") {
      return true;
    }
  } catch (_) { }
  return false;
}

/** Security headers ported from index.js's helmet() config. */
const SECURITY_HEADERS: Record<string, string> = {
  "Content-Security-Policy": "default-src 'none'; frame-ancestors 'none'",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Cross-Origin-Resource-Policy": "same-site",
  "Strict-Transport-Security": "max-age=63072000; includeSubDomains; preload",
  "Referrer-Policy": "no-referrer",
};

/**
 * Resolve the CORS header set for this request's Origin. No Origin header
 * (native app / server-to-server / curl) is allowed through, same as the
 * original `cors()` config. An Origin present but not on the allow-list gets
 * no `Access-Control-Allow-Origin` header, which makes the browser block the
 * response client-side (equivalent to the Express CORS error path).
 */
function corsHeaders(req: Request): Record<string, string> {
  const origin = req.headers.get("Origin");
  const headers: Record<string, string> = {
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-razorpay-signature",
    Vary: "Origin",
  };
  if (!origin) return headers; // non-browser caller — nothing to restrict
  if (isOriginAllowed(origin)) {
    headers["Access-Control-Allow-Origin"] = origin;
  }
  return headers;
}

function jsonResponse(req: Request, status: number, body: unknown, extraHeaders: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...SECURITY_HEADERS,
      ...corsHeaders(req),
      ...extraHeaders,
    },
  });
}

function rawResponse(req: Request, status: number, body: string, extraHeaders: Record<string, string> = {}): Response {
  return new Response(body, {
    status,
    headers: {
      ...SECURITY_HEADERS,
      ...corsHeaders(req),
      ...extraHeaders,
    },
  });
}

const MAX_BODY_BYTES = 64 * 1024; // 64kb — matches express.json({ limit: "64kb" })

/**
 * Reads the raw request body (capped at 64kb, mirroring the original body
 * limit) and returns both the raw text (needed for the webhook's HMAC check)
 * and the parsed JSON (empty object on parse failure — callers validate
 * their own required fields same as the Express routes did).
 */
async function readBody(req: Request): Promise<{ raw: string; json: any }> {
  const raw = await req.text();
  if (new TextEncoder().encode(raw).length > MAX_BODY_BYTES) {
    const e = new Error("Request body too large");
    (e as any).code = "BODY_TOO_LARGE";
    throw e;
  }
  let json: any = {};
  try {
    json = raw ? JSON.parse(raw) : {};
  } catch {
    json = {};
  }
  return { raw, json };
}

/** Handles the CORS preflight OPTIONS request every browser POST will send. */
function handlePreflight(req: Request): Response | null {
  if (req.method !== "OPTIONS") return null;
  return new Response(null, { status: 204, headers: { ...SECURITY_HEADERS, ...corsHeaders(req) } });
}

/** Rejects any method outside the small allow-list each route needs. */
function methodNotAllowed(req: Request, allow: string[]): Response | null {
  if (allow.includes(req.method)) return null;
  return jsonResponse(req, 405, { success: false, error: "Method not allowed" });
}

/* ============================== clients.ts ============================== */
// Supabase client factories.
//
//   supabaseAdmin() — SERVICE ROLE key. Bypasses RLS entirely. This is the
//     only client allowed to call create_order_tx / rate_limit_check (both
//     REVOKEd from anon/authenticated) and to read server-only tables
//     (pending_orders, rate_limits). Never send this key to a client.
//
//   supabaseForRequest(req) — ANON key + the caller's own Authorization
//     header forwarded through. Calling `.auth.getUser()` on this client
//     verifies the caller's JWT against the Auth server on every call.

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

let _admin: SupabaseClient | null = null;
function supabaseAdmin(): SupabaseClient {
  if (_admin) return _admin;
  _admin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
    auth: { autoRefreshToken: false, persistSession: false },
  });
  return _admin;
}

function supabaseForRequest(req: Request): SupabaseClient {
  const authHeader = req.headers.get("Authorization") || "";
  return createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    auth: { autoRefreshToken: false, persistSession: false },
    global: { headers: { Authorization: authHeader } },
  });
}

/* ============================== auth.ts ============================== */
// Auth and permission helpers for Supabase Edge Functions.
// Uses Supabase Auth + `profiles` table for all auth and role checks.

type AuthResult = { user: User; error: null } | { user: null; error: Response };

/**
 * Verifies the caller's Supabase JWT (sent as `Authorization: Bearer <token>`).
 * `supabase.auth.getUser()` round-trips to the Auth server, so this is a
 * fresh check every call — not just decoding a locally-cached claim, the
 * same guarantee the original's per-request `verifyIdToken()` gave.
 */
async function requireAuth(req: Request): Promise<AuthResult> {
    const header = req.headers.get("Authorization") || "";
    if (!/^Bearer .+$/.test(header)) {
        return { user: null, error: jsonResponse(req, 401, { success: false, error: "Not authenticated" }) };
    }
    const client = supabaseForRequest(req);
    const { data, error } = await client.auth.getUser();
    if (error || !data?.user) {
        return { user: null, error: jsonResponse(req, 401, { success: false, error: "Invalid or expired session. Please log in again." }) };
    }
    return { user: data.user, error: null };
}

/**
 * requireAuth() + a `profiles.role === 'admin'` check.
 */
async function requireAdmin(req: Request, admin: SupabaseClient): Promise<AuthResult> {
    const auth = await requireAuth(req);
    if (!auth.user) return auth;

    const { data: profile, error } = await admin.from("profiles").select("role").eq("id", auth.user.id).maybeSingle();
    if (error || !profile || profile.role !== "admin") {
        return { user: null, error: jsonResponse(req, 403, { success: false, error: "Admin access required" }) };
    }
    return auth;
}

/**
 * Admin-controlled kill switch. Reads settings/security's jsonb `data`.
 * A feature is disabled when `${feature}Enabled === false` OR `allDisabled === true`.
 * Missing row / missing flag → enabled (default-on), matching the original.
 */
async function isFeatureKilled(admin: SupabaseClient, feature: string): Promise<boolean> {
    try {
        const { data, error } = await admin.from("settings").select("data").eq("id", "security").maybeSingle();
        if (error || !data) return false;
        const d = data.data || {};
        if (d.allDisabled === true) return true;
        return d[`${feature}Enabled`] === false;
    } catch (e) {
        console.error("[isFeatureKilled] error:", e);
        return false; // don't take the whole site down if this read fails
    }
}

/**
 * Per-user block check. Reads `profiles.status`;
 * both 'blocked' and 'suspended' values are treated as blocked.
 */
async function isUserBlocked(admin: SupabaseClient, userId: string): Promise<boolean> {
    try {
        const { data, error } = await admin.from("profiles").select("status").eq("id", userId).maybeSingle();
        if (error || !data) return false;
        return data.status === "blocked" || data.status === "suspended";
    } catch (e) {
        console.error("[isUserBlocked] error:", e);
        return false;
    }
}

/**
 * Checks if a promo code expiryDate is past the current time. Port of
 * isPromoExpired — handles ISO strings and naive local datetime strings.
 * expiry_date is stored as `timestamptz`, so values read back from Postgres
 * are always timezone-aware ISO strings in practice; the naive-datetime
 * branch is kept for parity with hand-entered/legacy values.
 */
function isPromoExpired(expiryDate: string | number | null | undefined): boolean {
    if (!expiryDate) return false;
    let expTime: number;
    if (typeof expiryDate === "string" && !expiryDate.endsWith("Z") && !/[+-]\d{2}:\d{2}$/.test(expiryDate)) {
        const parts = expiryDate.split(/[-T:]/);
        if (parts.length >= 5) {
            expTime = new Date(
                Number(parts[0]),
                Number(parts[1]) - 1,
                Number(parts[2]),
                Number(parts[3]),
                Number(parts[4]),
            ).getTime();
        } else {
            expTime = new Date(expiryDate).getTime();
        }
    } else {
        expTime = new Date(expiryDate).getTime();
    }
    return !isNaN(expTime) && Date.now() > expTime;
}

/* ============================== rateLimit.ts ============================== */
// Port of functions/lib/util.js's rateLimit()/globalDailyLimit(), backed by
// the `rate_limit_check` Postgres function (02-order-rpc.sql) instead of a
// Firestore transaction. Same fixed-window semantics, same fail-closed
// default. Must be called with the SERVICE ROLE client — the RPC is REVOKEd
// from anon/authenticated.

/**
 * @param key     Unique bucket, e.g. `create-order:<uid>`
 * @param max     Max calls allowed per window
 * @param windowMs Window length in ms (converted to seconds for the RPC)
 * @param opts.failOpen  If true, allow the call when the limiter itself
 *        errors. Defaults to FAIL-CLOSED (deny), same as the original —
 *        a limiter outage must not be usable to bypass abuse protection on
 *        cost-bearing routes.
 */
async function rateLimit(
  admin: SupabaseClient,
  key: string,
  max: number,
  windowMs: number,
  opts: { failOpen?: boolean } = {},
): Promise<boolean> {
  const { failOpen = false } = opts;
  try {
    const { data, error } = await admin.rpc("rate_limit_check", {
      p_key: key,
      p_max: max,
      p_window_seconds: Math.round(windowMs / 1000),
    });
    if (error) throw error;
    return !!data;
  } catch (e) {
    console.error("[rateLimit] error:", e);
    return failOpen;
  }
}

/**
 * Global per-day counter — port of globalDailyLimit(). Reuses the same
 * rate_limit_check primitive: a day-stamped key (`global-<name>-<day>`) with
 * an 86400s window gives the identical "resets once a UTC day boundary is
 * crossed" behavior the original's day-string key achieved. FAIL-CLOSED.
 */
async function globalDailyLimit(admin: SupabaseClient, name: string, max: number, day: string): Promise<boolean> {
  try {
    const { data, error } = await admin.rpc("rate_limit_check", {
      p_key: `global-${name}-${day}`,
      p_max: max,
      p_window_seconds: 86400,
    });
    if (error) throw error;
    return !!data;
  } catch (e) {
    console.error("[globalDailyLimit] error:", e);
    return false; // fail-closed
  }
}

/* ============================== signature.ts ============================== */
// ^ DELIBERATE: plain-JavaScript subset of TypeScript (no annotations), so its unit test (supabase/tests/signature.test.mjs) also runs in a browser on a
//   machine without Node/Deno (tools/browser-test/Run-TsLiteTests.ps1) - the same convention as _shared/refundGateway.ts. Signature checks guard the
//   money paths (a forged "payment captured" webhook, a forged checkout signature), so they want to be EXECUTED, not just compiled.
//
// The signature primitives behind payment-verify (HMAC of "order_id|payment_id" with the key secret) and payment-webhook (HMAC of the RAW request body with the
// webhook secret). Phase 13 extracted them from razorpay.ts unchanged in behaviour, with one tightening: every check FAILS CLOSED - an empty / missing secret,
// a missing or non-string signature or payload answers `false` instead of computing a digest with an empty key or throwing.

/** HMAC-SHA256 of `data` (UTF-8) under `secret` (UTF-8), lower-case hex - the algorithm Razorpay documents (crypto.createHmac("sha256", secret).update(data).digest("hex")). */
async function hmacHex(secret, data) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, enc.encode(data));
  return Array.from(new Uint8Array(sig)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

/**
 * Constant-time string comparison (Deno's WebCrypto has no timingSafeEqual). A different LENGTH is refused at once: the length of a hex digest is not a secret.
 * Strings are compared as UTF-8 bytes; anything that is not a string is compared as its text.
 */
function timingSafeEqual(a, b) {
  const x = new TextEncoder().encode(String(a));
  const y = new TextEncoder().encode(String(b));
  if (x.length !== y.length) return false;
  let diff = 0;
  for (let i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
  return diff === 0;
}

/**
 * True ONLY when `signature` is the HMAC-SHA256 hex digest of `data` under `secret`. Never throws, and answers false when
 *   - the secret is not a non-empty string (a missing server secret must never validate anything: an HMAC with an empty key is a valid HMAC),
 *   - the payload is not a string, or the signature is not a non-empty string (an upper-case / padded / truncated digest does not match: Razorpay sends lower-case hex).
 */
async function verifyHmacSignature(secret, data, signature) {
  if (typeof secret !== "string" || secret === "") return false;
  if (typeof data !== "string") return false;
  if (typeof signature !== "string" || signature === "") return false;
  try {
    return timingSafeEqual(await hmacHex(secret, data), signature);
  } catch (_e) {
    return false;
  }
}

/* ============================== razorpay.ts ============================== */
// Razorpay integration — unchanged from functions/routes/payment.js, only
// the runtime moves (Cloud Function -> Edge Function). Same npm package,
// same HMAC-SHA256 signature scheme, same env var names. Keys are read from
// Edge Function secrets (`supabase secrets set`), never from client code.

let _razorpay: Razorpay | null = null;

/** Lazily builds the Razorpay client (env isn't present at deploy-analysis time). */
function getRazorpay(): Razorpay {
  if (_razorpay) return _razorpay;
  const key_id = Deno.env.get("RAZORPAY_KEY_ID");
  const key_secret = Deno.env.get("RAZORPAY_KEY_SECRET");
  if (!key_id || !key_secret) {
    throw new Error("Missing RAZORPAY_KEY_ID / RAZORPAY_KEY_SECRET env vars");
  }
  _razorpay = new Razorpay({ key_id, key_secret });
  return _razorpay;
}

// The HMAC primitives live in ./signature.ts (plain-JavaScript subset, unit-tested in supabase/tests/signature.test.mjs); they FAIL CLOSED: a missing
// secret or signature answers false (Phase 13 - before, a missing key secret made crypto.subtle throw, a missing webhook secret was handled here only).

/** Verifies a /verify payload's signature: HMAC(order_id|payment_id) with the key secret. */
async function verifyPaymentSignature(orderId: string, paymentId: string, signature: string): Promise<boolean> {
  return verifyHmacSignature(Deno.env.get("RAZORPAY_KEY_SECRET") || "", `${orderId}|${paymentId}`, String(signature));
}

/** Verifies a webhook payload's signature: HMAC(raw body) with the webhook secret. */
async function verifyWebhookSignature(rawBody: string, signature: string): Promise<boolean> {
  return verifyHmacSignature(Deno.env.get("RAZORPAY_WEBHOOK_SECRET") || "", rawBody, String(signature));
}

/* ============================== refundGateway.ts ============================== */
// ^ DELIBERATE. This file is written in the plain-JavaScript subset of TypeScript (no annotations, no `as`, no generics): it is valid TypeScript
//   for Deno / the bundler / `npm run typecheck` (the check is skipped for this one file), AND valid JavaScript, so its unit tests also run in a
//   browser on a machine without Node (tools/browser-test/Run-TsLiteTests.ps1 copies it to .js). Money logic wants to be executed, not just compiled.
//
// Refund <-> Razorpay glue shared by the refund-create function and the payment webhook (Phase 9).
//
// WHY THIS FILE EXISTS: the decisions that matter (may this refund be sent at all? was it sent already? what did the gateway answer?) are
// made by the DATABASE (refund_begin_gateway / refund_record_gateway_result / refund_apply_gateway_event, migration 20261017_06_refunds.sql).
// This file only (a) turns a database claim into a Razorpay API call, (b) turns the gateway's answer or failure into one of the three
// outcomes the database understands, and (c) is written against INJECTED clients (`admin` = the service-role Supabase client, `razorpay` =
// the SDK instance) so it can be unit-tested with fakes (supabase/tests/refundGateway.test.mjs - no network, no Deno).
//
// THE OUTCOMES: accepted (Razorpay created the refund: id + status), rejected (a definitive 4xx: NOTHING was created, the refund fails
// and a new one can be made) and unknown (no usable answer: the refund may or may not exist -> never resend, check the status).
// Every function returns { http, body } so index.ts is only an HTTP shell.

const DEFINITIVE_STATUS = [400, 401, 403, 404, 422];       // the request itself was refused: no refund exists
const UNKNOWN_STATE_MINUTES = 2;                           // a status check may conclude "never created" once the call is this old
const SUBMITTING_STALE_MINUTES = 5;                        // ... and a call that never reported back (the function died) once it is this old

/** Razorpay's own status word -> the three the database knows ('created' = accepted, still pending). */
function mapRazorpayRefundStatus(status) {
  const s = String(status ?? "").toLowerCase();
  if (s === "processed") return "processed";
  if (s === "failed") return "failed";
  return "pending";
}

/** Webhook event name (+ the entity's own status) -> the status word refund_apply_gateway_event() takes. */
function refundStatusFromEvent(event, entityStatus) {
  if (event === "refund.processed") return "processed";
  if (event === "refund.failed") return "failed";
  const s = String(entityStatus ?? "").toLowerCase();
  return s === "processed" || s === "failed" ? s : "created";
}

/** Razorpay notes: at most 15 string values of up to 256 characters. */
function sanitizeNotes(notes) {
  const out = {};
  const src = notes && typeof notes === "object" ? notes : {};
  for (const k of Object.keys(src).slice(0, 15)) {
    const v = src[k];
    if (v === null || v === undefined) continue;
    out[String(k).slice(0, 64)] = String(v).slice(0, 256);
  }
  return out;
}

/** The body of payments.refund(): the amount in paise (integer), a normal-speed refund, our refund number as the receipt, our ids as notes. */
function buildRefundParams(begin) {
  const amount = Math.round(Number(begin?.amount_paise));
  if (!Number.isFinite(amount) || amount <= 0) throw new Error("The refund amount is not valid");
  return { amount, speed: "normal", receipt: String(begin?.receipt ?? "").slice(0, 40), notes: sanitizeNotes(begin?.notes) };
}

/** Only what is safe and useful to keep of a Razorpay refund entity (never the whole object). */
function safeRefundPayload(entity) {
  const e = entity ?? {};
  return {
    id: e.id ?? null, status: e.status ?? null, amount: e.amount ?? null, currency: e.currency ?? null, payment_id: e.payment_id ?? null,
    receipt: e.receipt ?? null, speed_requested: e.speed_requested ?? null, speed_processed: e.speed_processed ?? null, created_at: e.created_at ?? null,
  };
}

/** A gateway failure -> { outcome: 'rejected' | 'unknown', message (short, no keys), payload (kept admin-only) }. */
function classifyGatewayError(err) {
  const e = err ?? {};
  const status = Number(e.statusCode ?? e.status ?? e.response?.status);
  const rz = e.error ?? e.response?.data?.error ?? {};
  const description = String(rz.description ?? e.message ?? "The payment gateway did not answer");
  const definitive = Number.isFinite(status) && DEFINITIVE_STATUS.includes(status);
  // never let a key or token slip into a message the customer might read
  const message = description.replace(/rzp_(live|test)_[A-Za-z0-9]+/g, "[key]").replace(/\s+/g, " ").trim().slice(0, 200);
  return {
    outcome: definitive ? "rejected" : "unknown",
    message,
    payload: { statusCode: Number.isFinite(status) ? status : null, code: String(rz.code ?? e.code ?? ""), description: description.slice(0, 500), field: rz.field ?? null, reason: rz.reason ?? null },
  };
}

/** Which of a payment's refunds is ours: by the id we put into the notes, else by the receipt (our refund number). */
function findOurRefund(items, refundId, receipt) {
  const list = Array.isArray(items) ? items : [];
  return list.find((r) => r?.notes?.refund_id === refundId) ?? list.find((r) => receipt && r?.receipt === receipt) ?? null;
}

const NOT_SENT_TEXT = {
  ALREADY_SENT: "This refund was already sent to Razorpay. Use \"Check status\" to follow it.",
  NOT_PENDING: "This refund is not pending any more.",
  WRONG_METHOD: "This is not a Razorpay refund.",
  NO_PAYMENT_ID: "The order has no Razorpay payment id, so it cannot be refunded through the gateway.",
};

/** SEND: claim the refund in the database, call Razorpay once, record the answer. Never sends twice (the claim is refused the second time). */
async function sendRefund(admin, razorpay, refundId) {
  const claim = await admin.rpc("refund_begin_gateway", { p_refund_id: refundId });
  if (claim.error) {
    return { http: claim.error.code === "P0002" ? 404 : 500, body: { success: false, code: "BEGIN_FAILED", error: claim.error.message || "Could not start the refund" } };
  }
  const begin = claim.data;
  if (!begin || !begin.proceed) {
    return { http: 409, body: { success: false, code: begin?.reason || "NOT_SENT", error: NOT_SENT_TEXT[String(begin?.reason)] || "This refund cannot be sent.", status: begin?.status || "", gatewayState: begin?.gateway_state || "" } };
  }

  let params;
  try {
    params = buildRefundParams(begin);
  } catch (err) {                                          // cannot happen for a refund the database created (amount > 0), but never leave a claim hanging
    const message = err instanceof Error ? err.message : "The refund amount is not valid";
    const saved = await admin.rpc("refund_record_gateway_result", { p_refund_id: refundId, p_outcome: "rejected", p_error: message, p_payload: { build: true } });
    if (saved.error) console.error("[refund-create] could not record the failed claim:", saved.error.message);
    return { http: 422, body: { success: false, code: "GATEWAY_REJECTED", error: message, status: "failed", gatewayState: "not_sent" } };
  }

  let entity;
  try {
    entity = await razorpay.payments.refund(begin.razorpay_payment_id, params);
  } catch (err) {
    const c = classifyGatewayError(err);
    const saved = await admin.rpc("refund_record_gateway_result", { p_refund_id: refundId, p_outcome: c.outcome, p_error: c.message, p_payload: c.payload });
    if (saved.error) console.error("[refund-create] could not record the gateway failure:", saved.error.message);
    if (c.outcome === "rejected") {
      return { http: 422, body: { success: false, code: "GATEWAY_REJECTED", error: `Razorpay refused the refund: ${c.message}`, status: "failed", gatewayState: "not_sent" } };
    }
    return { http: 502, body: { success: false, code: "GATEWAY_UNKNOWN", error: "Razorpay did not confirm the refund. Do not send it again - use \"Check status\" in a few minutes.", status: "pending", gatewayState: "unknown" } };
  }

  const saved = await admin.rpc("refund_record_gateway_result", {
    p_refund_id: refundId, p_outcome: "accepted", p_gateway_refund_id: entity?.id ?? null, p_gateway_status: mapRazorpayRefundStatus(entity?.status), p_payload: safeRefundPayload(entity),
  });
  if (saved.error) {
    console.error("[refund-create] Razorpay accepted the refund but recording it failed:", saved.error.message);
    return { http: 502, body: { success: false, code: "RECORD_FAILED", error: "Razorpay accepted the refund but saving that failed. Use \"Check status\" - it will find the refund.", status: "pending", gatewayState: "submitting" } };
  }
  const status = String(saved.data?.status ?? "pending");
  return {
    http: 200,
    body: {
      success: true, refundId, status, gatewayState: String(saved.data?.gateway_state ?? "submitted"),
      message: status === "succeeded" ? "Razorpay has refunded it." : "Sent to Razorpay. It is marked paid out when Razorpay confirms it (usually within minutes, sometimes a few days).",
    },
  };
}

/** CHECK STATUS: ask Razorpay what happened to a refund we already sent (or may have sent) and record it. Never creates a refund. */
async function reconcileRefund(admin, razorpay, refundId) {
  const ctxRes = await admin.rpc("refund_gateway_context", { p_refund_id: refundId });
  if (ctxRes.error) return { http: ctxRes.error.code === "P0002" ? 404 : 500, body: { success: false, code: "CONTEXT_FAILED", error: ctxRes.error.message || "Could not read the refund" } };
  const ctx = ctxRes.data;
  if (ctx.method !== "razorpay") return { http: 409, body: { success: false, code: "WRONG_METHOD", error: NOT_SENT_TEXT.WRONG_METHOD } };
  if (ctx.status !== "pending") return { http: 200, body: { success: true, refundId, status: ctx.status, gatewayState: ctx.gateway_state || "", message: `This refund is already ${ctx.status}.` } };
  if (ctx.gateway_state === "not_sent") return { http: 200, body: { success: true, refundId, status: "pending", gatewayState: "not_sent", message: "This refund has not been sent to Razorpay yet." } };

  let found = null;
  try {
    if (ctx.gateway_refund_id) found = await razorpay.refunds.fetch(ctx.gateway_refund_id);
    else found = findOurRefund((await razorpay.payments.fetchMultipleRefund(ctx.razorpay_payment_id, { count: 100 }))?.items, refundId, ctx.refund_no);
  } catch (err) {
    const c = classifyGatewayError(err);
    return { http: 502, body: { success: false, code: "GATEWAY_UNAVAILABLE", error: `Could not ask Razorpay: ${c.message}`, status: "pending", gatewayState: ctx.gateway_state || "" } };
  }

  if (found) {
    const saved = await admin.rpc("refund_record_gateway_result", {
      p_refund_id: refundId, p_outcome: "accepted", p_gateway_refund_id: found.id, p_gateway_status: mapRazorpayRefundStatus(found.status), p_payload: safeRefundPayload(found),
    });
    if (saved.error) return { http: 500, body: { success: false, code: "RECORD_FAILED", error: saved.error.message || "Could not save the gateway status" } };
    const status = String(saved.data?.status ?? "pending");
    return { http: 200, body: { success: true, refundId, status, gatewayState: String(saved.data?.gateway_state ?? "submitted"), message: status === "succeeded" ? "Razorpay has paid it out." : status === "failed" ? "Razorpay reports that the refund failed." : "Razorpay has it and is still processing it." } };
  }

  // Razorpay has no such refund. A refund call that was sent is visible at once, so after a short grace period "unknown" means "never created".
  const ageMinutes = Number(ctx.state_age_seconds ?? 0) / 60;
  const gone = (ctx.gateway_state === "unknown" && ageMinutes >= UNKNOWN_STATE_MINUTES) || (ctx.gateway_state === "submitting" && ageMinutes >= SUBMITTING_STALE_MINUTES);
  if (gone) {
    const saved = await admin.rpc("refund_record_gateway_result", { p_refund_id: refundId, p_outcome: "rejected", p_error: "Razorpay has no record of this refund - it was never created", p_payload: { reconciled: true } });
    if (saved.error) return { http: 500, body: { success: false, code: "RECORD_FAILED", error: saved.error.message || "Could not save the gateway status" } };
    return { http: 200, body: { success: true, refundId, status: String(saved.data?.status ?? "failed"), gatewayState: String(saved.data?.gateway_state ?? "not_sent"), message: "Razorpay has no record of this refund, so it was never created. You can create a new refund." } };
  }
  return { http: 200, body: { success: true, refundId, status: "pending", gatewayState: ctx.gateway_state || "", message: "Razorpay does not list this refund (yet). Try again in a few minutes." } };
}

/* ============================== function logic (index.ts) ============================== */
// refund-create — pays a REFUND back through Razorpay (admin only) or asks Razorpay what happened to one. IMPLEMENTATION_PLAN Phase 9.
//
// The refund itself (amount, lines, who may be refunded how much) is created and calculated by the database (create_refund / refund_calculate,
// migration 20261017_06_refunds.sql). This function is only the bridge to the gateway:
//   POST { refundId, action: "send" }       claim the refund in the database (refused if it was sent before), call the Razorpay Refund API for the
//                                           SAME payment, record the answer. A refund is "paid out" only when Razorpay says processed (here or by
//                                           the refund.processed webhook handled in payment-webhook).
//   POST { refundId, action: "reconcile" }  ask Razorpay what happened to a refund that was sent (or may have been: a lost answer) and record it.
//                                           Never creates a refund.
// The orchestration lives in _shared/refundGateway.ts (unit-tested with fakes: supabase/tests/refundGateway.test.mjs).
//
// NEEDS CREDENTIALS: RAZORPAY_KEY_ID / RAZORPAY_KEY_SECRET (the same secrets the payment functions already use; the key must be allowed to
// create refunds - Razorpay keys are by default). Without them the function answers 503 NOT_CONFIGURED and nothing is claimed or changed.
// BLOCKED-CREDENTIALS for end-to-end verification: it has been tested against a fake Razorpay only (see TESTING_CHECKLIST G20-G22).

Deno.serve(async (req) => {
  const preflight = handlePreflight(req);
  if (preflight) return preflight;
  const methodErr = methodNotAllowed(req, ["POST"]);
  if (methodErr) return methodErr;

  const admin = supabaseAdmin();

  try {
    const auth = await requireAdmin(req, admin);
    if (!auth.user) return auth.error;

    if (!(await rateLimit(admin, `refund:${auth.user.id}`, 20, 60000, { failOpen: false }))) {
      return jsonResponse(req, 429, { success: false, code: "RATE_LIMITED", error: "Too many requests. Please wait a moment." });
    }

    const { json: body } = await readBody(req);
    const refundId = String(body?.refundId || "");
    const action = body?.action === "reconcile" ? "reconcile" : body?.action === "send" || body?.action === undefined ? "send" : "";
    if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(refundId) || !action) {
      return jsonResponse(req, 400, { success: false, code: "BAD_REQUEST", error: "refundId (uuid) and action (send | reconcile) are required" });
    }

    // before anything is claimed in the database: is the gateway configured at all?
    let razorpay: ReturnType<typeof getRazorpay>;
    try {
      razorpay = getRazorpay();
    } catch (_e) {
      return jsonResponse(req, 503, { success: false, code: "NOT_CONFIGURED", error: "Razorpay is not configured on the server (RAZORPAY_KEY_ID / RAZORPAY_KEY_SECRET)." });
    }

    const reply = action === "send" ? await sendRefund(admin, razorpay, refundId) : await reconcileRefund(admin, razorpay, refundId);
    return jsonResponse(req, reply.http, reply.body);
  } catch (err) {
    console.error("[refund-create] failed:", err);
    return jsonResponse(req, 500, { success: false, code: "FAILED", error: "The refund request failed. Check the refund's status before trying again." });
  }
});